109:     /**
110:      * @dev Updates the Oracle snapshot for a given Well and returns the deltaB
111:      * given the previous snapshot in the Well
112:      */
113:     function updateOracle(
114:         address well,
115:         bytes memory lastSnapshot
116:     ) internal returns (int256 deltaB) {
117:         AppStorage storage s = LibAppStorage.diamondStorage();
118:         uint256[] memory twaReserves;
119:         uint256[] memory ratios;
120:         (deltaB, s.sys.wellOracleSnapshots[well], twaReserves, ratios) = twaDeltaB(
121:             well,
122:             lastSnapshot
123:         );
124: 
125:         // Set the Well reserves in storage, so that it can be read when
126:         // 1) set the USD price of the non bean token so that it can be read when
127:         //    calculating the price of Bean. See {LibEvaluate.evalPrice}.
128:         // 2) When calculating the Bean reward for calling the Season (Bean:Eth Only).
129:         //    See {LibIncentive.determineReward}.
130:         LibWell.setTwaReservesForWell(well, twaReserves);
131:         LibWell.setUsdTokenPriceForWell(well, ratios);
132:         emit WellOracle(s.sys.season.current, well, deltaB, s.sys.wellOracleSnapshots[well]);
133:     }
134: 
135:     /**
136:      * @dev Calculates the time weighted average delta B since the input snapshot for
137:      * a given Well address.
138:      */
139:     function twaDeltaB(
140:         address well,
141:         bytes memory lastSnapshot
142:     ) internal view returns (int256, bytes memory, uint256[] memory, uint256[] memory) {
143:         AppStorage storage s = LibAppStorage.diamondStorage();
144:         // Try to call `readTwaReserves` and handle failure gracefully, so Sunrise does not revert.
145:         // On failure, reset the Oracle by returning an empty snapshot and a delta B of 0.
146:         Call[] memory pumps = IWell(well).pumps();
147:         try
148:             ICumulativePump(pumps[0].target).readTwaReserves(
149:                 well,
150:                 lastSnapshot,
151:                 uint40(s.sys.season.timestamp),
152:                 pumps[0].data
153:             )
154:         returns (uint[] memory twaReserves, bytes memory snapshot) {
155:             IERC20[] memory tokens = IWell(well).tokens();
156:             (uint256[] memory ratios, uint256 beanIndex, bool success) = LibWell
157:                 .getRatiosAndBeanIndex(tokens, block.timestamp.sub(s.sys.season.timestamp));
158: 
159:             // If the Bean reserve is less than the minimum, the minting oracle should be considered off.
160:             if (twaReserves[beanIndex] < C.WELL_MINIMUM_BEAN_BALANCE) {
161:                 return (0, snapshot, new uint256[](0), new uint256[](0));
162:             }
163: 
164:             // If the USD Oracle oracle call fails, the minting oracle should be considered off.
165:             if (!success) {
166:                 return (0, snapshot, twaReserves, new uint256[](0));
167:             }
168: 
169:             Call memory wellFunction = IWell(well).wellFunction();
170:             // Delta B is the difference between the target Bean reserve at the peg price
171:             // and the time weighted average Bean balance in the Well.
172:             int256 deltaB = int256(
173:                 IBeanstalkWellFunction(wellFunction.target).calcReserveAtRatioSwap(
174:                     twaReserves,
175:                     beanIndex,
176:                     ratios,
177:                     wellFunction.data
178:                 )
179:             ).sub(int256(twaReserves[beanIndex]));
180: 
181:             return (deltaB, snapshot, twaReserves, ratios);
182:         } catch {
183:             // if the pump fails, return all 0s to avoid the sunrise reverting.
184:             return (0, new bytes(0), new uint256[](0), new uint256[](0));
185:         }
186:     }
187: }
